(function () {
  var fl = Java.loadClass('net.fabricmc.loader.api.FabricLoader');
  var all = fl.getInstance().getAllMods();
  var ids = [];
  var it = all.iterator();
  while (it.hasNext()) { ids.push(String(it.next().getMetadata().getId())); }
  var need = ['astral_dice','autojs','sodium','iris','jei','jade','modmenu','cloth-config','lithium','immediatelyfast','ferritecore','collective','superflatworldnoslimes','modernfix','trinkets'];
  var missing = [];
  for (var i = 0; i < need.length; i++) { if (ids.indexOf(need[i]) < 0) { missing.push(need[i]); } }
  var forbidden = [];
  for (var j = 0; j < ids.length; j++) { if (ids[j] === 'accessories' || ids[j] === 'accessories_compat_layer') { forbidden.push(ids[j]); } }
  return { count: ids.length, missing: missing, forbidden: forbidden, astral: ids.indexOf('astral_dice') >= 0 };
})()
